data Note = Note
  { noteFirst :: !(Maybe Int32)
  , noteSecond :: !(Maybe Int32)
  , noteUnknownFields :: ![UnknownField]
  }
  deriving stock (Show, Eq, Generic)
  deriving anyclass NFData

defaultNote :: Note
defaultNote = Note
  { noteFirst = Nothing
  , noteSecond = Nothing
  , noteUnknownFields = []
  }

instance MessageEncode Note where
  buildMessage msg =
    (maybe mempty (\v -> archVarint 8 (fromIntegral v)) msg.noteFirst)
    <> (maybe mempty (\v -> archVarint 16 (fromIntegral v)) msg.noteSecond)
    <> encodeUnknownFields msg.noteUnknownFields

instance MessageSize Note where
  messageSize msg =
    (maybe 0 (\v -> archVarintSize (fromIntegral v)) msg.noteFirst)
    + (maybe 0 (\v -> archVarintSize (fromIntegral v)) msg.noteSecond)
    + unknownFieldsSize msg.noteUnknownFields

instance MessageDecode Note where
  {-# INLINE messageDecoder #-}
  messageDecoder = loop Nothing Nothing []
    where
      loop acc_0 acc_1 acc_unknown_ = withTagM
        (pure (Note {noteFirst = acc_0, noteSecond = acc_1, noteUnknownFields = reverse acc_unknown_}))
        (\fn wt -> case fn of
          1 | wt == 0 -> do
            v <- (fromIntegral <$> decodeFieldVarint)
            loop (Just v) acc_1 acc_unknown_
          2 | wt == 0 -> do
            v <- (fromIntegral <$> decodeFieldVarint)
            loop acc_0 (Just v) acc_unknown_
          _ -> do
            uf <- captureUnknownField fn (toEnum wt)
            loop acc_0 acc_1 (uf : acc_unknown_))

instance ProtoMessage Note where
  protoMessageName _ = "Note"
  protoPackageName _ = ""
  protoDefaultValue = defaultNote
  protoFileDescriptorBytes _ = fileDescriptorProtoBytes
  protoFieldDescriptors _ = Map.fromList
    [ (1, SomeField FieldDescriptor
        { fdName = "first"
        , fdNumber = 1
        , fdTypeDesc = ScalarType Int32Field
        , fdLabel = LabelOptional
        , fdGet = noteFirst
        , fdSet = \v m -> m { noteFirst = v }
        }), (2, SomeField FieldDescriptor
        { fdName = "second"
        , fdNumber = 2
        , fdTypeDesc = ScalarType Int32Field
        , fdLabel = LabelOptional
        , fdGet = noteSecond
        , fdSet = \v m -> m { noteSecond = v }
        })
    ]

instance IsMessage Note

instance Aeson.ToJSON Note where
  toJSON msg = jsonObject
      (concat
        [ maybe [] (\value -> [("first", Aeson.toJSON value)]) msg.noteFirst
        , maybe [] (\value -> [("second", Aeson.toJSON value)]) msg.noteSecond
        ])

instance Aeson.FromJSON Note where
  parseJSON = Aeson.withObject "Note" $ \obj -> do
    fld_noteFirst <- PJ.parseFieldMaybeWith PJ.protoInt32FromJSON obj "first"
    fld_noteSecond <- PJ.parseFieldMaybeWith PJ.protoInt32FromJSON obj "second"
    pure defaultNote
      { noteFirst = fld_noteFirst
      , noteSecond = fld_noteSecond
      , noteUnknownFields = []
      }

instance Hashable Note where
  hashWithSalt salt msg = hashWithSalt (hashWithSalt (salt) msg.noteFirst) msg.noteSecond

instance Proto.Extension.HasExtensions Note where
  messageUnknownFields = noteUnknownFields
  setMessageUnknownFields !ufs msg = msg { noteUnknownFields = ufs }

instance Semigroup Note where
  a <> b = Note
    { noteFirst = case b.noteFirst of { Nothing -> a.noteFirst; x -> x }
    , noteSecond = case b.noteSecond of { Nothing -> a.noteSecond; x -> x }
    , noteUnknownFields = a.noteUnknownFields <> b.noteUnknownFields
    }

instance Monoid Note where
  mempty = defaultNote

