data OneofDefaults = OneofDefaults
  { oneofDefaultsSelection :: !(Maybe OneofDefaults'Selection)
  , oneofDefaultsUnknownFields :: ![UnknownField]
  }
  deriving stock (Show, Eq, Generic)
  deriving anyclass NFData

data OneofDefaults'State
  = OneofDefaults'State'First
  | OneofDefaults'State'Second
  | OneofDefaults'State''Unrecognized !Int32
  deriving stock (Show, Eq, Ord, Generic)
  deriving anyclass NFData

toProtoEnumOneofDefaults'State :: OneofDefaults'State -> Int
toProtoEnumOneofDefaults'State OneofDefaults'State'First = 0
toProtoEnumOneofDefaults'State OneofDefaults'State'Second = 1
toProtoEnumOneofDefaults'State (OneofDefaults'State''Unrecognized n) = fromIntegral n

fromProtoEnumOneofDefaults'State :: Int -> Maybe OneofDefaults'State
fromProtoEnumOneofDefaults'State (0) = Just OneofDefaults'State'First
fromProtoEnumOneofDefaults'State (1) = Just OneofDefaults'State'Second
fromProtoEnumOneofDefaults'State _ = Nothing

instance Enum OneofDefaults'State where
  fromEnum = toProtoEnumOneofDefaults'State
  toEnum n = case fromProtoEnumOneofDefaults'State n of
    Just v -> v
    Nothing -> OneofDefaults'State''Unrecognized (fromIntegral n)

instance Bounded OneofDefaults'State where
  minBound = OneofDefaults'State'First
  maxBound = OneofDefaults'State'Second

instance ProtoEnum OneofDefaults'State where
  protoEnumName _ = "OneofDefaults.State"
  protoEnumValues _ = [("FIRST", 0), ("SECOND", 1)]
  fromProtoEnumValue = fromProtoEnumOneofDefaults'State
  toProtoEnumValue = toProtoEnumOneofDefaults'State
  protoEnumIsOpen _ = False

instance MessageEncode OneofDefaults'State where
  buildMessage _ = mempty
instance MessageSize OneofDefaults'State where
  messageSize _ = 0
instance MessageDecode OneofDefaults'State where
  messageDecoder = pure (toEnum 0)

instance Aeson.ToJSON OneofDefaults'State where
  toJSON OneofDefaults'State'First = Aeson.String "FIRST"
  toJSON OneofDefaults'State'Second = Aeson.String "SECOND"
  toJSON (OneofDefaults'State''Unrecognized n) = Aeson.toJSON n

instance Aeson.FromJSON OneofDefaults'State where
  parseJSON value = case value of
    Aeson.String "FIRST" -> pure OneofDefaults'State'First
    Aeson.String "SECOND" -> pure OneofDefaults'State'Second
    v -> PJ.protoEnumNumberFromJSON v

instance Hashable OneofDefaults'State where
  hashWithSalt salt x = hashWithSalt salt (toProtoEnumOneofDefaults'State x)
data OneofDefaults'Selection
  = OneofDefaults'Selection'State !OneofDefaults'State
  | OneofDefaults'Selection'Raw !ByteString
  | OneofDefaults'Selection'Count {-# UNPACK #-} !Int32
  deriving stock (Show, Eq, Generic)
  deriving anyclass NFData
instance Aeson.ToJSON OneofDefaults'Selection where
  toJSON _ = Aeson.Null
instance Aeson.FromJSON OneofDefaults'Selection where
  parseJSON _ = fail "Cannot parse oneof from JSON"
instance Hashable OneofDefaults'Selection where
  hashWithSalt salt (OneofDefaults'Selection'State v) = salt `hashWithSalt` (0 :: Int) `hashWithSalt` v
  hashWithSalt salt (OneofDefaults'Selection'Raw v) = salt `hashWithSalt` (1 :: Int) `hashWithSalt` v
  hashWithSalt salt (OneofDefaults'Selection'Count v) = salt `hashWithSalt` (2 :: Int) `hashWithSalt` v

defaultOneofDefaults :: OneofDefaults
defaultOneofDefaults = OneofDefaults
  { oneofDefaultsSelection = Nothing
  , oneofDefaultsUnknownFields = []
  }

instance MessageEncode OneofDefaults where
  buildMessage msg =
    (case msg.oneofDefaultsSelection of
      Nothing -> mempty
      Just (OneofDefaults'Selection'State v) -> archVarint 8 (fromIntegral (fromEnum v))
      Just (OneofDefaults'Selection'Raw v) -> archBytes 18 v
      Just (OneofDefaults'Selection'Count v) -> archSVarint32 24 v)
    <> encodeUnknownFields msg.oneofDefaultsUnknownFields

instance MessageSize OneofDefaults where
  messageSize msg =
    (case msg.oneofDefaultsSelection of { Nothing -> 0; Just (OneofDefaults'Selection'State v) -> archVarintSize (fromIntegral (fromEnum v))
    ; Just (OneofDefaults'Selection'Raw v) -> archBytesSize v
    ; Just (OneofDefaults'Selection'Count v) -> (1 + varintSize (fromIntegral (zigZag32 v))) })
    + unknownFieldsSize msg.oneofDefaultsUnknownFields

instance MessageDecode OneofDefaults where
  {-# INLINE messageDecoder #-}
  messageDecoder = loop Nothing []
    where
      loop acc_0 acc_unknown_ = withTagM
        (pure (OneofDefaults {oneofDefaultsSelection = acc_0, oneofDefaultsUnknownFields = reverse acc_unknown_}))
        (\fn wt -> case fn of
          1 | wt == 0 -> decodeProtoEnum 1
            (\v -> loop (Just (OneofDefaults'Selection'State v)) acc_unknown_)
            (\uf -> loop acc_0 (uf : acc_unknown_))
          2 | wt == 2 -> do
            v <- decodeFieldBytes
            loop (Just (OneofDefaults'Selection'Raw v)) acc_unknown_
          3 | wt == 0 -> do
            v <- decodeFieldSVarint32
            loop (Just (OneofDefaults'Selection'Count v)) acc_unknown_
          _ -> do
            uf <- captureUnknownField fn (toEnum wt)
            loop acc_0 (uf : acc_unknown_))

instance ProtoMessage OneofDefaults where
  protoMessageName _ = "OneofDefaults"
  protoPackageName _ = ""
  protoDefaultValue = defaultOneofDefaults
  protoFileDescriptorBytes _ = fileDescriptorProtoBytes
  protoFieldDescriptors _ = Map.fromList
    [ (1, SomeField FieldDescriptor
        { fdName = "selection"
        , fdNumber = 1
        , fdTypeDesc = MessageType "selection"
        , fdLabel = LabelOptional
        , fdGet = oneofDefaultsSelection
        , fdSet = \v m -> m { oneofDefaultsSelection = v }
        })
    ]
  protoOneofDescriptors _ =
    [ PSchema.OneofDescriptor "selection" [ PSchema.OneofFieldDescriptor "state" 1 (EnumType "State") (if protoEnumIsOpen (Proxy :: Proxy OneofDefaults'State) then Nothing else Just (map snd (protoEnumValues (Proxy :: Proxy OneofDefaults'State))))
    , PSchema.OneofFieldDescriptor "raw" 2 (ScalarType BytesField) Nothing
    , PSchema.OneofFieldDescriptor "count" 3 (ScalarType SInt32Field) Nothing ] ]
  protoJSONIgnoreUnknownEnumNames _ = PJ.normalizeEnumJSONFields
    [ PJ.EnumJSONField "state" "state" (PJ.normalizeEnumJSONValue (Proxy :: Proxy OneofDefaults'State)) ]

instance IsMessage OneofDefaults

instance Aeson.ToJSON OneofDefaults where
  toJSON msg = jsonObject
      (concat
        [ case msg.oneofDefaultsSelection of
            { Nothing -> []
            ; Just (OneofDefaults'Selection'State v) -> [( "state"
            , Aeson.toJSON v )]
            ; Just (OneofDefaults'Selection'Raw v) -> [( "raw"
            , PJ.protoBytesToJSON v )]
            ; Just (OneofDefaults'Selection'Count v) -> [( "count"
            , Aeson.toJSON v )]
            }

        ])

instance Aeson.FromJSON OneofDefaults where
  parseJSON = Aeson.withObject "OneofDefaults" $ \obj -> do
    fld_oneofDefaultsSelection <- PJ.parseOneofVariants obj
      [ PJ.OneofVariant "state" "state" False (\v -> OneofDefaults'Selection'State <$> Aeson.parseJSON v)
      , PJ.OneofVariant "raw" "raw" False (\v -> OneofDefaults'Selection'Raw <$> PJ.protoBytesFromJSON v)
      , PJ.OneofVariant "count" "count" False (\v -> OneofDefaults'Selection'Count <$> PJ.protoInt32FromJSON v) ]
    pure defaultOneofDefaults
      { oneofDefaultsSelection = fld_oneofDefaultsSelection
      , oneofDefaultsUnknownFields = []
      }

instance Hashable OneofDefaults where
  hashWithSalt salt msg = hashWithSalt (salt) msg.oneofDefaultsSelection

instance Proto.Extension.HasExtensions OneofDefaults where
  messageUnknownFields = oneofDefaultsUnknownFields
  setMessageUnknownFields !ufs msg = msg { oneofDefaultsUnknownFields = ufs }

instance Semigroup OneofDefaults where
  a <> b = OneofDefaults
    { oneofDefaultsSelection = case b.oneofDefaultsSelection of { Nothing -> a.oneofDefaultsSelection; x -> x }
    , oneofDefaultsUnknownFields = a.oneofDefaultsUnknownFields <> b.oneofDefaultsUnknownFields
    }

instance Monoid OneofDefaults where
  mempty = defaultOneofDefaults